// lib/engine/packs/centro_corsi.js
//
// Sector Pack "centro_corsi" v1 — conoscenza di SETTORE (centro corsi e
// formazione in Italia: lingue, informatica, musica, corsi professionali; non
// di un singolo centro). In lib/settori.js il cliente e' l'"Iscritto" e
// l'evento e' la "Lezione". Prezzi, rate, sconti, calendari, livelli, orari,
// sedi, docenti, certificazioni effettivamente rilasciate, lezione di prova e
// politica sui recuperi NON stanno qui: arrivano solo dai dati del tenant. Il
// lessico riconosce le parole che usa l'iscritto (anche per corsi, livelli e
// certificazioni che un centro specifico potrebbe non avere): riconoscere
// "Cambridge" o "chitarra" in un messaggio non significa che il centro li offra.
//
// Note di progetto (specifiche del settore):
//  - L'urgenza e' RARA e di tipo diverso da quello sanitario: pericolo per
//    l'incolumita' (malore, incendio, aggressione, molestie, minore che non si
//    trova) -> CRITICAL con rimando al 112; infortunio o minore non rintracciabile,
//    esame imminente, accesso impossibile a una lezione online in corso -> HIGH.
//  - "urgente" da solo e' HIGH solo come frase esplicita ("e urgente"): una
//    richiesta di iscrizione "subito" NON e' un'urgenza.
//  - Il bot non promette esiti (superare un esame, imparare in X mesi, trovare
//    lavoro) ne' validita'/riconoscimento di un titolo, ne' stima costi: sono
//    richieste "sensibili" (risposta di sicurezza, poi persona se insistono).
//  - Prova gratuita / lezione di prova / test di livello esistono solo se il
//    tenant li offre: l'intent di prenotazione della prova NON propone slot
//    in automatico (create_lead/notify_owner): la conferma arriva da una persona
//    o dai dati del tenant.
//  - Iscritto minorenne: per firma, consenso, delega, liberatorie e pagamenti
//    il referente e' il genitore/tutore e la parte contrattuale va a una persona
//    (intent HUMAN_HANDOFF "contratto_minore"; l'iscrizione di un minore non
//    propone mai slot).
//  - Disdette, ritiri, rimborsi, spostamenti e recuperi di lezioni gia' fissate
//    vanno sempre a una persona (il sistema non modifica iscrizioni esistenti).
//  - Fuzzy del motore (1 refuso su parole >= 6 lettere): le voci di lessico non
//    usano parole che a distanza 1 collidono con termini comuni.
//
// Il motore non cambia: un nuovo settore e' solo dati.

export const SETTORE = 'centro_corsi';
export const VERSIONE = 1;
export const CHANGELOG = 'v1: primo Sector Pack centro corsi e formazione — lessico (lingue, informatica, musica, corsi professionali, livelli, formati, certificazioni, minorenni, azienda), 32 intent, 14 entità, urgenze di incolumità (CRITICAL 112) e infortunio/minore non rintracciabile (HIGH), sicurezza su promesse di esito/validità titoli/livello, prova e minorenni senza slot automatici, FAQ di settore generali senza importi né orari.';

